mapper.select:
SELECT DISTINCT ON (c.emd_cd)
    c.emd_cd    AS emdCd,
    c.crdn_mthd AS crdnMthd,
    COUNT(*)    AS mthdCnt
FROM parking.tb_crdn_dsctn c
WHERE c.crdn_dt::date BETWEEN #{startDt} AND #{endDt}
  AND c.emd_cd IS NOT NULL
  AND NULLIF(BTRIM(c.crdn_mthd), '') IS NOT NULL
AND LEFT(c.emd_cd, 5) = #{sggCd}
AND c.emd_cd = #{emdCd}
AND c.crdn_type_cd = #{cvlcptTypeCd}
GROUP BY c.emd_cd, c.crdn_mthd
ORDER BY c.emd_cd ASC, COUNT(*) DESC, c.crdn_mthd ASC

SELECT
    ROUND(c.lat::numeric, 3) AS lat,
    ROUND(c.lot::numeric, 3) AS lot,
    COUNT(*)                 AS cnt
FROM parking.tb_cvlcpt c
WHERE c.ocrn_dt::date BETWEEN #{startDt} AND #{endDt}
  AND c.emd_cd IS NOT NULL
  AND c.cvlcpt_type_cd <> '99'
  AND c.lat IS NOT NULL AND c.lot IS NOT NULL
AND LEFT(c.emd_cd, 5) = #{sggCd}
AND c.emd_cd = #{emdCd}
AND c.cvlcpt_type_cd = #{cvlcptTypeCd}
GROUP BY 1, 2

SELECT
    ROUND(c.lat::numeric, 3) AS lat,
    ROUND(c.lot::numeric, 3) AS lot,
    COUNT(*)                 AS cnt
FROM parking.tb_crdn_dsctn c
WHERE c.crdn_dt::date BETWEEN #{startDt} AND #{endDt}
  AND c.emd_cd IS NOT NULL
  AND c.lat IS NOT NULL AND c.lot IS NOT NULL
AND LEFT(c.emd_cd, 5) = #{sggCd}
AND c.emd_cd = #{emdCd}
AND c.crdn_type_cd = #{cvlcptTypeCd}
GROUP BY 1, 2
